// Package mcpserver serves protobuf services as MCP tools with the text and
// behaviour declared in their raveesh_me.http_proto_lint.v1 options.
//
// Code generated by protoc-gen-go-mcp registers the tools. Wrap sits between
// that code and the official MCP Go SDK: it names each tool after its RPC in
// snake_case (GetTodo becomes get_todo), replaces the comment-based
// description with the declared tool title and description, adds the
// declared MCP ToolAnnotations, and passes the caller's headers on.
//
// Forward the generated tools to a Connect client whose HTTP client is
// InProcessClient(api), so every MCP call runs through the same auth, scope
// checks, flow IDs and error audit as REST and RPC calls.
package mcpserver

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"regexp"
	"strings"
	"unicode"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/redpanda-data/protoc-gen-go-mcp/pkg/gen"
	"github.com/redpanda-data/protoc-gen-go-mcp/pkg/runtime"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protoreflect"

	hplv1 "github.com/raveesh-me/http-proto-lint/gen/go/raveesh_me/http_proto_lint/v1"
)

// forwardedHeaders are copied from the MCP request onto the forwarded call.
var forwardedHeaders = []string{"Authorization", "X-Flow-ID"}

// validName is the tool name format every MCP client and LLM provider accepts.
var validName = regexp.MustCompile(`^[a-z_][a-z0-9_-]{0,63}$`)

type server struct {
	s       *mcp.Server
	methods map[string]protoreflect.MethodDescriptor // generated tool name to method
}

// Wrap returns a runtime.MCPServer that registers the tools of the services
// on s. Pass it to the generated ForwardToConnect<Service>Client functions.
// It fails when two RPCs would get the same short tool name, which happens
// only when services sharing a server have RPCs of the same name.
func Wrap(s *mcp.Server, services ...protoreflect.ServiceDescriptor) (runtime.MCPServer, error) {
	methods := map[string]protoreflect.MethodDescriptor{}
	short := map[string]protoreflect.FullName{}
	for _, svc := range services {
		for i := 0; i < svc.Methods().Len(); i++ {
			m := svc.Methods().Get(i)
			name := ToolName(m)
			if !validName.MatchString(name) {
				return nil, fmt.Errorf("mcpserver: %s: tool name %q is not a valid MCP tool name", m.FullName(), name)
			}
			if prev, taken := short[name]; taken {
				return nil, fmt.Errorf("mcpserver: %s and %s both map to tool %q; serve them from separate MCP servers", prev, m.FullName(), name)
			}
			short[name] = m.FullName()
			methods[gen.ToolForMethod(m, "").Name] = m
		}
	}
	return &server{s: s, methods: methods}, nil
}

// ToolName returns the MCP tool name of an RPC: its name in snake_case, such
// as get_todo for GetTodo.
func ToolName(m protoreflect.MethodDescriptor) string {
	runes := []rune(string(m.Name()))
	var b strings.Builder
	for i, r := range runes {
		if unicode.IsUpper(r) && i > 0 {
			prevLower := unicode.IsLower(runes[i-1]) || unicode.IsDigit(runes[i-1])
			nextLower := i+1 < len(runes) && unicode.IsLower(runes[i+1])
			if prevLower || (unicode.IsUpper(runes[i-1]) && nextLower) {
				b.WriteByte('_')
			}
		}
		b.WriteRune(unicode.ToLower(r))
	}
	return b.String()
}

// AddTool implements runtime.MCPServer.
func (w *server) AddTool(tool runtime.Tool, handler runtime.ToolHandler) {
	w.s.AddTool(w.describe(tool), func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		args := map[string]any{}
		if raw := req.Params.Arguments; len(raw) > 0 {
			if err := json.Unmarshal(raw, &args); err != nil {
				return nil, err
			}
		}
		if req.Extra != nil {
			ctx = withHeaders(ctx, req.Extra.Header)
		}
		result, err := handler(ctx, &runtime.CallToolRequest{Arguments: args})
		if err != nil || result == nil {
			return nil, err
		}
		return &mcp.CallToolResult{
			Content:           []mcp.Content{&mcp.TextContent{Text: result.Text}},
			StructuredContent: result.StructuredContent,
			IsError:           result.IsError,
		}, nil
	})
}

// describe builds the SDK tool from the declared options, falling back to
// what protoc-gen-go-mcp derived from comments.
func (w *server) describe(tool runtime.Tool) *mcp.Tool {
	out := &mcp.Tool{
		Name:        tool.Name,
		Description: tool.Description,
		InputSchema: json.RawMessage(tool.RawInputSchema),
	}
	if len(tool.RawOutputSchema) > 0 {
		out.OutputSchema = json.RawMessage(tool.RawOutputSchema)
	}
	m, ok := w.methods[tool.Name]
	if !ok {
		return out
	}
	out.Name = ToolName(m)
	rules, _ := proto.GetExtension(m.Options(), hplv1.E_Method).(*hplv1.MethodRules)
	if d := rules.GetTool().GetDescription(); d != "" {
		out.Description = d
	}
	out.Title = rules.GetTool().GetTitle()
	out.Annotations = annotations(rules.GetTool())
	out.InputSchema = describeSchema(tool.RawInputSchema, m.Input())
	return out
}

// annotations returns the ToolAnnotations declared in the proto, as the MCP
// specification (2026-07-28) defines them. An undeclared hint is left out,
// so clients apply the specification's default; HOUSE_TOOL_ANNOTATIONS makes
// sure every hint that applies is declared.
func annotations(tool *hplv1.Tool) *mcp.ToolAnnotations {
	a := tool.GetAnnotations()
	if a == nil {
		a = &hplv1.ToolAnnotations{}
	}
	return &mcp.ToolAnnotations{
		Title:           tool.GetTitle(),
		ReadOnlyHint:    a.GetReadOnlyHint(),
		IdempotentHint:  a.GetIdempotentHint(),
		DestructiveHint: copyBool(a.DestructiveHint),
		OpenWorldHint:   copyBool(a.OpenWorldHint),
	}
}

func copyBool(b *bool) *bool {
	if b == nil {
		return nil
	}
	v := *b
	return &v
}

// describeSchema sets the input schema's description from the request
// message's declared description.
func describeSchema(raw json.RawMessage, input protoreflect.MessageDescriptor) json.RawMessage {
	rules, _ := proto.GetExtension(input.Options(), hplv1.E_Message).(*hplv1.MessageRules)
	if rules.GetDescription() == "" {
		return raw
	}
	var schema map[string]any
	if err := json.Unmarshal(raw, &schema); err != nil {
		return raw
	}
	schema["description"] = rules.GetDescription()
	out, err := json.Marshal(schema)
	if err != nil {
		return raw
	}
	return out
}

type headersKey struct{}

func withHeaders(ctx context.Context, h http.Header) context.Context {
	kept := http.Header{}
	for _, name := range forwardedHeaders {
		if v := h.Get(name); v != "" {
			kept.Set(name, v)
		}
	}
	return context.WithValue(ctx, headersKey{}, kept)
}
